/* Equipment pagination and accessible full-value hover: additive, no data mutation. */
(()=>{'use strict';let active=null,observer=null,page=1;const LIMIT=10;
function mount(){const root=document.querySelector('#equipment .eq-page');if(!root||!root.querySelector('.eq-wo-select'))return;if(root===active)return;active=root;page=1;const card=root.querySelector('.eq-table-card');if(!card)return;const nav=document.createElement('nav');nav.className='eq-pagination';nav.setAttribute('aria-label','설비 목록 페이지 이동');card.after(nav);let busy=false;
function update(){if(busy||!root.isConnected)return;busy=true;try{const rows=[...root.querySelectorAll('.eq-table tbody tr')];const eligible=rows.filter(r=>r.dataset.eqBaseFiltered!=='0');const pages=Math.max(1,Math.ceil(eligible.length/LIMIT));page=Math.min(page,pages);eligible.forEach((r,i)=>{r.style.display=(Math.floor(i/LIMIT)+1===page)?'':'none';r.querySelectorAll('td').forEach(td=>{if(!td.title)td.title=td.textContent.trim()})});rows.filter(r=>r.dataset.eqBaseFiltered==='0').forEach(r=>r.style.display='none');nav.innerHTML='';const btn=(label,p,disabled,current)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;if(current)b.setAttribute('aria-current','page');b.addEventListener('click',()=>{page=p;update()});nav.appendChild(b)};btn('‹',Math.max(1,page-1),page===1,false);for(let i=1;i<=pages;i++)btn(String(i),i,false,i===page);btn('›',Math.min(pages,page+1),page===pages,false);nav.hidden=pages===1}catch(e){console.warn('Equipment page update:',e)}finally{busy=false}}
const tbody=root.querySelector('.eq-table tbody');if(observer)observer.disconnect();observer=new MutationObserver(muts=>{let rerender=false;for(const m of muts){if(m.type==='childList'&&m.addedNodes.length)rerender=true}if(rerender){page=1;setTimeout(()=>{tbody.querySelectorAll('tr').forEach(r=>r.dataset.eqBaseFiltered='1');update()},0)}});observer.observe(tbody,{childList:true});root.querySelectorAll('.eq-parity-filters input,.eq-parity-filters select').forEach(el=>el.addEventListener('input',()=>{page=1;setTimeout(()=>{tbody.querySelectorAll('tr').forEach(r=>{r.dataset.eqBaseFiltered=r.style.display==='none'?'0':'1'});update()},60)}));tbody.querySelectorAll('tr').forEach(r=>r.dataset.eqBaseFiltered='1');update()}
new MutationObserver(()=>{const p=document.querySelector('#equipment .eq-page');if(p&&p!==active)mount()}).observe(document.body,{childList:true,subtree:true});mount();
})();